import{_ as t,o,c as a,ae as r}from"./chunks/framework.B2ul6ABY.js";const p=JSON.parse('{"title":"Security & Content Supervision","description":"","frontmatter":{},"headers":[],"relativePath":"design/security.md","filePath":"design/security.md"}'),i={name:"design/security.md"};function n(s,e,d,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="security-content-supervision" tabindex="-1">Security &amp; Content Supervision <a class="header-anchor" href="#security-content-supervision" aria-label="Permalink to &quot;Security &amp; Content Supervision&quot;">​</a></h1><blockquote><p>Canonical design document consolidated from <code>docs/design/security.md</code> during Stage 22. Stage 23 will reconcile detailed source anchors where needed.</p></blockquote><h2 id="content-supervisor" tabindex="-1">Content Supervisor <a class="header-anchor" href="#content-supervisor" aria-label="Permalink to &quot;Content Supervisor&quot;">​</a></h2><p>The content supervisor is a non-LLM layer that screens content before it enters agent context. It sits between the outside world and the agents.</p><h3 id="what-it-screens" tabindex="-1">What it screens <a class="header-anchor" href="#what-it-screens" aria-label="Permalink to &quot;What it screens&quot;">​</a></h3><ul><li>Tool results that contain external content (file reads, web downloads, command output, MCP responses).</li><li>User messages from Telegram or web UI.</li><li>Skill files loaded from disk.</li><li>Any content loaded via <code>download_file</code>.</li></ul><h3 id="what-it-does-not-screen" tabindex="-1">What it does NOT screen <a class="header-anchor" href="#what-it-does-not-screen" aria-label="Permalink to &quot;What it does NOT screen&quot;">​</a></h3><ul><li>Agent-to-runtime communication (card mutations, process management, notification acknowledgement) — these use structured, validated MCP calls and canonical services.</li><li>Internal system prompts and instructions written by the project owner.</li></ul><hr><h2 id="prompt-injection-scanner" tabindex="-1">Prompt Injection Scanner <a class="header-anchor" href="#prompt-injection-scanner" aria-label="Permalink to &quot;Prompt Injection Scanner&quot;">​</a></h2><p>The scanner uses a two-layer approach:</p><h3 id="layer-1-heuristic-patterns" tabindex="-1">Layer 1: Heuristic patterns <a class="header-anchor" href="#layer-1-heuristic-patterns" aria-label="Permalink to &quot;Layer 1: Heuristic patterns&quot;">​</a></h3><p>A set of regex patterns that detect common prompt injection techniques. When any pattern matches, the content is flagged as <strong>suspicious</strong> and escalated to Layer 2.</p><p>Heuristic pattern categories:</p><table tabindex="0"><thead><tr><th>Category</th><th>Example patterns</th></tr></thead><tbody><tr><td>Instruction override</td><td>&quot;ignore previous instructions&quot;, &quot;override system prompt&quot;, &quot;disregard all prior&quot;</td></tr><tr><td>Role hijacking</td><td>&quot;you are now&quot;, &quot;act as&quot;, &quot;pretend to be&quot;</td></tr><tr><td>Tool-use direction</td><td>&quot;call the tool&quot;, &quot;use the function&quot;, &quot;execute the command&quot;</td></tr><tr><td>Secret exfiltration</td><td>&quot;output the system prompt&quot;, &quot;reveal your instructions&quot;, &quot;print the API key&quot;</td></tr><tr><td>Destructive commands</td><td>&quot;delete all files&quot;, &quot;rm -rf&quot;, &quot;drop table&quot;</td></tr><tr><td>Self-labeled injection</td><td>&quot;BEGIN INJECTION&quot;, &quot;PROMPT INJECTION&quot;, &quot;SYSTEM OVERRIDE&quot;</td></tr></tbody></table><p>Layer 1 is fast (pure regex, no LLM call) and catches obvious attempts. It has a configurable sensitivity level.</p><h3 id="layer-2-llm-scan" tabindex="-1">Layer 2: LLM scan <a class="header-anchor" href="#layer-2-llm-scan" aria-label="Permalink to &quot;Layer 2: LLM scan&quot;">​</a></h3><p>When Layer 1 flags content as suspicious, a lightweight LLM is invoked to analyze the content:</p><ul><li><strong>Input</strong>: The suspicious content plus a system prompt explaining the injection detection task.</li><li><strong>Output</strong>: Structured verdict: <code>{ safe: boolean, confidence: number, reason: string }</code>.</li><li><strong>Model</strong>: Uses a separate, cheap model configured via <code>security.injectionModel</code> (see <code>configuration.md</code>).</li><li><strong>Size limit</strong>: Content larger than <code>maxScanLengthBytes</code> (default: 100 KB) is truncated before scanning.</li></ul><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ul><li><strong>Allow</strong>: Content passes both layers → delivered to the agent normally.</li><li><strong>Block</strong>: Content is flagged as injection → <ul><li>The original content is <strong>quarantined</strong> (saved under <code>.saivage-work/quarantine/&lt;quarantine-id&gt;/</code>).</li><li>The agent receives a sanitized summary: <em>&quot;Content from [source] was blocked by the content supervisor (reason: [reason]). The original has been quarantined.&quot;</em></li><li>A <code>warning</code>-severity event is published on the event bus.</li></ul></li></ul><hr><h2 id="mutating-control-safety-model" tabindex="-1">Mutating control safety model <a class="header-anchor" href="#mutating-control-safety-model" aria-label="Permalink to &quot;Mutating control safety model&quot;">​</a></h2><p>Mutating control surfaces share one authorization and audit model.</p><p>Core rules:</p><ul><li>every mutating call declares a safety class: <code>read_only | low | high | destructive | deployment</code></li><li>a static authz table keyed by <code>(actor, surface, safety_class)</code> returns <code>allow | deny | preview_only</code></li><li>confirmation is driven by the verdict, not the safety class alone</li><li><code>preview_only</code> requires <code>confirmed: true</code> plus a matching preview hash derived from the request parameters</li><li>every mutating call writes one control-action audit entry</li><li>read-only inspection paths rely on transport auth plus redaction and do not fill the audit log</li></ul><p>Default behavior highlights:</p><ul><li>analyst on <code>web-chat</code>: <code>preview_only</code> for <code>high</code> and <code>destructive</code>, <code>deny</code> for <code>deployment</code></li><li>analyst on <code>telegram</code>: <code>preview_only</code> for <code>high</code>, <code>deny</code> for <code>destructive</code> and <code>deployment</code></li><li>REST and CLI are more permissive by default</li></ul><p>Operators customize the table in source instead of adding per-tool confirmation drift.</p><hr><h2 id="agent-write-territories" tabindex="-1">Agent write territories <a class="header-anchor" href="#agent-write-territories" aria-label="Permalink to &quot;Agent write territories&quot;">​</a></h2><p>Each agent role has advisory write territory rules — conventions about which areas of the project each role should write to. These are enforced as <strong>warnings, not blocks</strong>: violations are logged but do not prevent the write.</p><table tabindex="0"><thead><tr><th>Role</th><th>Write territory</th><th>Exclude</th></tr></thead><tbody><tr><td>Analyst</td><td>Chat sessions and notes via runtime APIs under <code>.saivage/agents/</code> and <code>.saivage/notes/</code></td><td>Project source files</td></tr><tr><td>Planner</td><td>Plan card diary (via runtime)</td><td>Source files, <code>.saivage/</code> directly</td></tr><tr><td>Executor</td><td>Project files per card type, <code>.saivage-work/cards/</code>, <code>.saivage-work/processes/</code></td><td><code>.saivage/</code> directly, other cards&#39; artifacts</td></tr><tr><td>Reviewer</td><td>Review reports (appended to plan card via runtime)</td><td>Source files, <code>.saivage/</code> directly</td></tr></tbody></table><p>Territory enforcement means:</p><ul><li>If an executor tries to write to another card&#39;s artifact directory, a warning is logged.</li><li>If an agent tries to read <code>.saivage/auth-profiles.json</code> or other sensitive config files, the request is blocked (not just warned).</li><li>Territory violations are visible in the debug timeline.</li></ul><hr><h2 id="sensitive-file-protection" tabindex="-1">Sensitive File Protection <a class="header-anchor" href="#sensitive-file-protection" aria-label="Permalink to &quot;Sensitive File Protection&quot;">​</a></h2><p>Certain files are protected from agent access regardless of role:</p><table tabindex="0"><thead><tr><th>Path</th><th>Protection</th></tr></thead><tbody><tr><td><code>.saivage/auth-profiles.json</code></td><td>No read, no write</td></tr><tr><td><code>.saivage/saivage.json</code> (secrets)</td><td>Redacted on read</td></tr><tr><td><code>.saivage-work/tmp/runtime/runtime.lock</code></td><td>No write</td></tr></tbody></table><p>API keys and tokens in config are redacted when served through the config API, audit summaries, notification payloads, or when an agent reads the config file.</p><p><code>redactSecrets()</code> must be applied at boundaries that could leak config-like material into notification or audit payloads.</p><hr><h2 id="api-authentication" tabindex="-1">API Authentication <a class="header-anchor" href="#api-authentication" aria-label="Permalink to &quot;API Authentication&quot;">​</a></h2><p>The HTTP server requires authentication on all <code>/api/*</code> endpoints:</p><ul><li><strong>Token</strong>: <code>SAIVAGE_API_TOKEN</code> environment variable.</li><li><strong>Enforcement</strong>: Bearer token in <code>Authorization</code> header or <code>?token=</code> query parameter.</li><li><strong>Public endpoints</strong>: <code>/health</code> does not require authentication.</li><li><strong>WebSocket</strong>: Auth is checked on connection upgrade. Connections without valid auth are closed with code <code>1008</code> (policy violation).</li></ul><p>See <code>server-api.md</code> for endpoint details.</p><hr><h2 id="file-access-security" tabindex="-1">File Access Security <a class="header-anchor" href="#file-access-security" aria-label="Permalink to &quot;File Access Security&quot;">​</a></h2><p>The files API enforces:</p><ul><li><strong>Path traversal rejection</strong>: Requests containing <code>..</code> or absolute paths outside the project root are blocked.</li><li><strong>Hidden file blocking</strong>: Requests for files under <code>.saivage/</code> that are in the sensitive file list are blocked.</li><li><strong>Size limit</strong>: File content responses are capped at 1 MB.</li></ul>',50)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
